window.REC_META = {"repo": "vending-solana", "subtitle": "FastAPI, Solana Pay y un relé gobernado por TCP", "description": "Máquina expendedora con pago cripto: el kiosco crea la orden, muestra un QR de Solana Pay y espera el pago on-chain. Cuando la transacción valida, dispensa la bebida y deja registro para conciliación.", "repo_url": "https://github.com/jmadasme/vending-solana", "page_url": "https://jmadasme.github.io/vending-solana/", "poster_text": "Máquina expendedora con pago cripto: el kiosco crea la orden, muestra un QR de Solana Pay y espera el pago on-chain. Cuando la transacción valida, dispensa la bebida y deja registro para conciliación.", "commands": ["cp .env.example .env", "uvicorn app:app --host 0.0.0.0 --port 8000 --workers 1", "sudo systemctl status vending-unoq"], "chapters": [{"time": "0:06", "label": "EL PROBLEMA", "title": "Elegir, pagar y dispensar sin intermediarios"}, {"time": "0:21", "label": "ARQUITECTURA", "title": "Wallet, ATA y monitor en el arranque"}, {"time": "0:36", "label": "CATÁLOGO", "title": "Ocho bebidas, ocho precios, un YAML"}, {"time": "0:49", "label": "LA ORDEN", "title": "El total se recalcula, nunca se confía"}, {"time": "1:04", "label": "COBRO", "title": "Un QR que el wallet pueda leer"}, {"time": "1:18", "label": "RESILIENCIA", "title": "Si el RPC falla, hay respaldo"}, {"time": "1:31", "label": "VALIDACIÓN", "title": "Una transacción no es un pago hasta validarla"}, {"time": "1:47", "label": "CONCILIACIÓN", "title": "Emparejar pago y orden sin confiar en el QR"}, {"time": "2:04", "label": "DISPENSADO", "title": "Dispensar es secuencial, no en paralelo"}, {"time": "2:18", "label": "HARDWARE", "title": "El relé no se dispara dos veces"}, {"time": "2:35", "label": "MCU", "title": "La UNO Q no expone GPIO: habla por TCP"}], "width": 104, "height": 34, "duration": 178.82, "title": "Vending Solana: una máquina que cobra en USDC"};
